<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'; import {getProducts} from '~/services/productService'; import type {Product} from '~/types/product'
const products=ref<Product[]>([]); onMounted(async()=>products.value=await getProducts()); const accessories=computed(()=>products.value.filter(p=>(p.categoryName||'').toLowerCase().includes('accessor')).slice(0,6))
</script>
<template><section class="max-w-7xl mx-auto px-8 py-12"><div class="flex justify-between items-center mb-6"><h2 class="text-xl font-bold">Accessories</h2><NuxtLink to="/accessories" class="text-sm text-blue-600">View all</NuxtLink></div><div v-if="accessories.length" class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4"><NuxtLink v-for="p in accessories" :key="p.productId" :to="`/products/${p.productId}?from=accessories`" class="bg-white rounded-xl border p-4 hover:shadow-lg"><div class="h-36 flex items-center justify-center"><img :src="p.image" :alt="p.name" class="max-h-full max-w-full object-contain"/></div><p class="text-sm font-semibold text-center mt-4 line-clamp-2">{{p.name}}</p><p class="text-xs text-gray-500 text-center mt-2">{{p.price!=null?`$${Number(p.price).toFixed(2)}`:'View options'}}</p></NuxtLink></div><p v-else class="text-center text-gray-500 py-8">No accessory products are currently available.</p></section></template>
